T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "Suite-Optik, Schrift, Mindesthöhe und Position für Blizzard-Dialoge, markierte Wiederbelebungsangebote, die Gegenstandsqualität als Wort auf Beutemeldungen und golden gerahmte Geldmeldungen.")
T("A bar cannot attach to itself.", "Eine Leiste kann nicht an sich selbst angeheftet werden.")
T("A bar cannot send cooldowns to itself.", "Eine Leiste kann keine Abklingzeiten an sich selbst senden.")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "Ein filmreifer Suite-Bildschirm mit deinem Charakter, während du AFK bist. Bewege dich oder nutze /afk, um zurückzukehren.")
T("A class in your group can provide this buff.", "Eine Klasse in deiner Gruppe kann diesen Stärkungszauber wirken.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "Eine aufgeräumte Minikarte in eigenem Frame: Größe, Form, Rahmen, Zoom, Blizzard-Buttons, eine Addon-Schublade und Infotexte. Blizzards Minikarten-Buttons funktionieren weiter.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "Eine klickdurchlässige Fläche folgt jedem Blizzard-Chatfenster. Blizzards und MSUFs Bearbeitungsmodus behalten ihre normalen Steuerungen zum Verschieben und Ändern der Größe.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "Eine farbige Platte liegt hinter der Karte und ihrem Rahmen. Der Innenabstand vergrößert sie über den Kartenrand hinaus.")
T("A compact clock, FPS and latency bar.", "Eine kompakte Leiste für Uhrzeit, FPS und Latenz.")
T("A compact, movable history of your recent successful spells.", "Ein kompakter, verschiebbarer Verlauf deiner zuletzt erfolgreich gewirkten Zauber.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "Eine Bildratenanzeige kann unter der Leiste oder für sich sitzen und wird im MSUF-Bearbeitungsmodus platziert. Die MSUF-Suite-FPS-Tastenbelegung zeigt oder verbirgt sie für diese Sitzung, auch im Kampf; eine neue Auswahl hier ersetzt diesen Sitzungsschalter.")
T("A movable strip for critical strike, haste, mastery and versatility.", "Eine verschiebbare Leiste für kritische Trefferchance, Tempo, Meisterschaft und Vielseitigkeit.")
T("A movable summary after a Mythic+ run or raid boss kill.", "Eine verschiebbare Zusammenfassung nach einem Mythisch+-Durchlauf oder Raidboss-Kill.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "Ein gut sichtbarer Ring um den Mauszeiger, optional gefüllt von deiner globalen Abklingzeit oder deinem Zauber.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "Ein Ring um den Mauszeiger, damit du ihn leicht findest. Wähle Form, Größe, Farbe, eine kurze Spur und einen Mittelpunkt; „Kein Ring“ behält nur den Punkt oder die Fortschrittsfüllung. Der Kameramodus zeigt Ring, Punkt und Spur nur, während du eine Maustaste auf der Spielwelt gedrückt hältst, um die Kamera zu drehen. Die Hervorhebung folgt dem Zeiger nur, solange etwas angezeigt wird, und bewegt nichts, während der Zeiger ruht.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "Eine kleine Übersicht sitzt neben dem Charakter-Reiter deines Charakterfensters und verschwindet mit ihm. Sie listet deine Ausrüstung mit Sockeln und wie viele gefüllt sind, offene in Bernstein (klicke eine Zeile, um zu sockeln), die Gesamthaltbarkeit deiner Ausrüstung und auf Wunsch deine PvP-Gegenstandsstufe. Ihre Knöpfe öffnen die Große Schatzkammer und die aktuelle Erweiterungsseite. Sie aktualisiert sich, während das Fenster offen ist, höchstens einmal pro Frame.")
T("A soft light behind the map, independent of the border and artwork.", "Ein weiches Licht hinter der Karte, unabhängig von Rahmen und Grafik.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "Eine Übersicht mit Sockeln, Haltbarkeit, PvP-Gegenstandsstufe sowie Knöpfen für die Große Schatzkammer und die Erweiterung, Haltbarkeit am Modell, zugeschnittene Platzsymbole und Gegenstandsstufen in der Ausrüstungsauswahl.")
T("A valid spell name does not confirm a matching target aura. Custom IDs remain selected until you disable them.", "Ein gültiger Zaubername bestätigt keine passende Zielaura. Eigene IDs bleiben ausgewählt, bis du sie deaktivierst.")
T("A waypoint cannot be set on this map", "Auf dieser Karte kann kein Wegpunkt gesetzt werden")
T("A weekly reward is available.", "Eine wöchentliche Belohnung ist verfügbar.")
