T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "Ergänzt Blizzards eigene Einstellung „Automatisch plündern“, die unverändert bleibt, um automatisches Einsammeln. Gesperrte Plätze und Bestätigungen bleiben manuell.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "Ergänzt Blizzards Haupttooltip um Gildenrang, das Ziel der Einheit, Gegenstandsstufen, das aktuelle Reittier der Einheit sowie Gegenstands- und Zauberdetails und kann Spielernamen ohne Titel zeigen. Deine eigene Gegenstandsstufe und die der Einheit im Betrachten-Fenster brauchen keine Anfrage. Gegenstandsstufen anderer überfahrener Spieler sind eine eigene Option, die Betrachten-Anfragen sendet: höchstens eine pro Überfahren und nie, solange das Betrachten-Fenster oder eine andere Betrachtung beschäftigt ist. Reittiere werden einmal beim Öffnen eines Einheitentooltips außerhalb des Kampfes gelesen; ein Wechsel erscheint beim nächsten Überfahren. Die feste Ecke platzierst du im MSUF-Bearbeitungsmodus; die Cursorversätze gelten für den Cursoranker.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "Zeigt im Haupttooltip eines anderen Spielers dessen Mythic+-Wertung der aktuellen Saison an, wenn Blizzard einen öffentlichen Wert liefert. Unbekannte oder geschützte Werte bleiben verborgen.")
T("Adjust the glass effect while keeping your colors and window coverage.", "Passe den Glaseffekt an, ohne deine Farben und die Fensterabdeckung zu ändern.")
T("Adventure Guide", "Abenteuerführer")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "Zeigt nach einem abgeschlossenen Mythisch+-Durchlauf oder einem besiegten Raidboss die verfügbaren Ergebnisse auf einer eigenen Karte. Lege fest, welche Kennzahlen erscheinen und wie lange die Karte sichtbar bleibt. Das letzte Ergebnis kann hier erneut geöffnet werden. Im Kampf erscheint die Karte erst nach Kampfende.")
