T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "Ein benachbarter Knopf öffnet ein kleines Menü für Erweiterung, Große Schatzkammer, Abenteuerführer und Weltkarte. Blizzards ursprünglicher Knopf behält seine Klickfunktion. Die Menüaktionen sind im Kampf deaktiviert.")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "Eine leere Erlaubnisliste schließt jede Quest ein. Trenne Quest-IDs mit Leerzeichen oder Kommas. Ausschlüsse für Tages- und Wochenquests lassen eine Quest manuell, wenn ihre Häufigkeit nicht lesbar ist. Bestehende Profile behalten ihr bisheriges Verhalten, bis du einen Ausschluss aktivierst.")
