T("Blizzard keeps every original font size and style flag.", "Blizzard behält jede ursprüngliche Schriftgröße und jedes Stilattribut.")
T("Blizzard keeps its text sizes and outlines.", "Blizzard behält seine Textgrößen und Konturen.")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "Blizzard behält Buttongrafik, Klicks, Tooltips, Aktivierungszustände und Benachrichtigungen. Optionale Glyphengrafik gibt es in den Detaileinstellungen. Optische Änderungen greifen nur außerhalb des Kampfes.")
T("Blizzard layout captured", "Blizzard-Layout erfasst")
T("Blizzard layout imported", "Blizzard-Layout übernommen")
T("Blizzard original", "Blizzard-Original")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "Blizzard steuert Aggroblinken, progressive Hervorhebungen und Soft-Target-Symbole. Optionale Farben tönen Blizzards vorhandene Bedrohungstexturen; die Bedrohungsfarbe des Lebensbalkens bleibt unter der Rollenfarbe. Soft-Target-Symbole benötigen außerdem aktivierte Namensplakettensymbole und ein passendes Soft-Target im Spiel.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "Blizzard steuert die Aurensymbole und ihre Aktualisierung. Wähle für jeden Einheitentyp „Blizzard-Einstellung behalten“ oder „Anpassen“. Buffs, Debuffs und Kontrolleffekte lassen sich in der Vorschau einzeln auswählen und ziehen. Die Aurengröße nutzt Blizzards eigene Einstellung.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "Blizzard steuert diese Elemente. Die Einstellung für das Seltenheitssymbol gilt für alle Namensplaketten; Zielmarkierungen werden nur auf feindlichen Plaketten ausgeblendet. Die Zauberleistendetails steuern Blizzards eigene Zauberleiste. Vorschau und echte Plaketten nutzen dieselben Schalter.")
T("Blizzard personal auras", "Persönliche Blizzard-Auren")
T("Blizzard plate size (health bar + elements)", "Blizzard-Plakettengröße (Lebensleiste + Elemente)")
T("Blizzard plate style", "Blizzard-Plakettenstil")
T("Blizzard raid target icon on enemy plates", "Blizzard-Zielmarkierung auf feindlichen Plaketten")
T("Blizzard setting", "Blizzard-Einstellung")
T("Blizzard shield", "Blizzard-Schild")
T("Blizzard spell icon", "Blizzard-Zaubersymbol")
T("Blizzard supplies health and aura updates. List edits and preview work during combat; color pickers work after combat.", "Blizzard liefert Gesundheit und Aura-Updates. Liste und Vorschau sind im Kampf bearbeitbar; Farbauswahl funktioniert nach dem Kampf.")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "Blizzard liefert Textur, Farben, Fortschritt und Unterbrechungen der Zauberleiste. Passe hier Text und Details an. Wähle jedes Zauberelement in der Vorschau aus und verschiebe es; Positionen werden außerhalb des Kampfes übernommen.")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "Blizzard liefert die Symbole. Die Suite behält eigene Buttonplatten, Leistenrahmen und Abstände. Originale Klicks, Tooltips und Benachrichtigungen bleiben erhalten.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "Blizzard liefert Namen und Lebenswerte. Mapko fordert vollständige gegnerische Namensplaketten und beide Lebenswerte an, damit auch normale Gegner Text anzeigen. Breite und Höhe ändern nur den gegnerischen Lebensbalken in Pixeln; 0 behält die gewählten Balkenmaße bei. Hintergrund, Rand und Rollenfüllung sind eigene Live-Skin-Ebenen in der Vorschau; ein Rechtsklick auf eine Ebene öffnet ihre Einstellung. Rollenfarben verwenden die gespeicherte Palette; Mana ist nur ein Hinweis auf Zauberwirker. Öffne hier das Dreipunktmenü oder Namensplaketten unter MSUF-Farben, um die Palette zu ändern.")
