T("Choose %s for \"%s\".", "Wähle %s für „%s“.")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "Wähle Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark oder Klassenstil für das Skinning und aktive Suite-Module. Später aktivierte Module übernehmen den Look.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Wähle Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever oder Klassenstil. Das ändert nur die Farben und Deckkraft des Taschenfensters; Gegenstandsplätze und Blizzards Taschenfunktionen bleiben erhalten.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Wähle Clean Modern, Midnight Blue, neutrales Midnight-Dark-Glas oder den dunkelgoldenen Rahmen von MSUF Forever. Alle nutzen MSUFs Balkentextur und Schrift. Die 20 EP-Teilstriche kannst du ein- oder ausschalten. Die untere Zeile kann Sitzungsgewinn, EP pro Stunde und Zeit bis zum Stufenaufstieg zeigen. Verschiebe oder skaliere den Balken im MSUF-Bearbeitungsmodus; im Popup änderst du X, Y, Breite, Höhe und Skalierung. Fahre für genaue Werte mit der Maus darüber. Eine Sitzung übersteht /reload und beginnt bei der nächsten Anmeldung neu.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Wähle das Layout „Benutzerdefiniert“, um die Reihenfolge von Gesamt-, Pro-Sekunde- und Prozentwerten festzulegen, und wähle dann Leerzeichen, Klammern oder ein Trennzeichen. Der Prozentschalter steuert die Hauptzeilen; Aufschlüsselungszeilen zeigen verfügbare Anteile. Nicht verfügbare Anteile werden weggelassen. Primär bedeutet pro Sekunde bei DPS/HPS und Gesamt bei anderen Anzeigen. Texteinstellungen gelten auch für Kopfzeilen, Details und den schwebenden Timer. Slug nutzt WoWs scharfen Schrift-Renderer mit Kontur und ohne Schatten. Geschützte Werte erscheinen bis zum Kampfende ohne Prozentangabe.")
T("Choose DoTs for this specialization. Disabled entries keep their position.", "Wähle DoTs für diese Spezialisierung. Deaktivierte Einträge behalten ihre Position.")
