T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "Wähle einen Look und wann die Suite-Leiste erscheint. Sichtbarkeitsregeln nutzen das Suite-Layout; das Blizzard-Layout behält Blizzards Sichtbarkeit. Der MSUF-Bearbeitungsmodus zeigt die Leiste zum Verschieben an.")
T("Choose a look below; this sample follows your changes.", "Wähle unten einen Look; dieses Beispiel folgt deinen Änderungen.")
T("Choose a look, then adjust its colors.", "Wähle einen Stil und passe seine Farben an.")
