T("Choose a preset below or fine-tune with the slider.", "Wähle unten eine Vorlage oder stelle den Regler fein ein.")
T("Choose a profile that exists in both parts of the suite", "Wähle ein Profil, das in beiden Teilen der Suite existiert")
T("Choose a random owned Hearthstone variant for the next click", "Für den nächsten Klick eine zufällige vorhandene Ruhesteinvariante wählen")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Wähle eine kleinere Stapelgröße und stelle sicher, dass der Gegenstand nicht gesperrt ist, dein Cursor leer ist und du nicht im Kampf bist.")
T("Choose a sound", "Sound wählen")
T("Choose a starting point. Existing bars stay unchanged.", "Wähle eine Vorlage. Vorhandene Leisten bleiben unverändert.")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Wähle oben einen Stil oder ändere diese Farben für ein eigenes Erscheinungsbild. Die Zeilen werden sofort aktualisiert.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "Wähle Stil, Schrift und Abdeckung in wenigen Minuten. Alle weiteren Einstellungen bleiben im Expertenmodus verfügbar.")
T("Choose a template", "Wähle eine Vorlage")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Wähle eine MSUF-Schriftart, Kontur, Schatten und die Darstellung Weich, Scharf oder Slug. Slug hat keinen Schatten. Farben für Beschriftung, Wert und Warnung sind getrennt.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Wähle eine MSUF- oder SharedMedia-Schriftart und Leistentextur. Schriftgröße, Kontur, Schatten, Darstellung (Weich/Scharf/Slug), Leistenhöhe und Abstand aktualisieren das HUD sofort. Slug hat keinen Schatten.")
T("Choose at least one DoT to enable aura colors", "Mindestens einen DoT für Aura-Farben auswählen")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Wähle grobe UI-Bereiche. Geschütztes Verhalten und bedeutungstragende Grafiken bleiben unangetastet.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Wähle Brokernamen und entdeckte Währungs-IDs pro Platz. Wähle deine Wappenwährungen der aktuellen Saison aus der nativen Währungsliste; gespeicherte Währungen funktionieren nach dem Login ohne Besuch beim Aufwertungs-NPC. Auswahlreihenfolge und Trennzeichen steuern den Wappenblock. Beobachtete Aufwertungsstufen bleiben als Alternative verfügbar, nachdem du in diesem Login ein Aufwertungsitem ausgewählt hast. Ruhesteinaktionen erfordern einen bewussten Klick.")
T("Choose buffs and consumables to track.", "Wähle die zu verfolgenden Stärkungszauber und Verbrauchsgüter.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "Wähle klare Fensterbuttons und einen kompletten Microleisten-Stil; passe einzelne Grafiken nur bei Bedarf an.")
T("Choose coverage", "Abdeckung wählen")
T("Choose crest currencies", "Wappenwährungen auswählen")
T("Choose currencies", "Währungen wählen")
T("Choose data", "Datentext auswählen")
T("Choose data for place %d", "Daten für Platz %d wählen")
T("Choose data source", "Datenquelle auswählen")
T("Choose discovered currency", "Bekannte Währung auswählen")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Wähle jedes Blizzard-Popup einzeln aus. Die Funktion blendet sein Fenster beim Erscheinen aus; die zugrunde liegenden Spielereignisse bleiben erhalten. Im Kampf kann das Ausblenden eines geschützten Fensters verhindert werden.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Wähle einzelne wiederkehrende UI-Fehler aus, die mit Blizzards eigenem Nachrichtenfilter ausgeblendet werden sollen.")
T("Choose loaded broker", "Geladenes Broker-Plugin auswählen")
T("Choose modules", "Module auswählen")
T("Choose observed seasonal stages", "Beobachtete saisonale Stufen auswählen")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Wähle eine Schrift für Blizzard-UI-Texte. Vorhandene Größen, Umrisse, Schatten und Barrierefreiheits-Skalierung bleiben erhalten.")
T("Choose preview DoTs", "Vorschau-DoTs auswählen")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Wähle die detaillierte Charakteransicht und ihre Zusatzinformationen. Ein Wechsel der Ansicht lädt die UI neu.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Wähle die Dungeon-Schwierigkeitsgrade, in denen MSUF das Kampflog startet. Mythisch+ beginnt mit dem Start des Schlüsselsteins.")
T("Choose the map shape, then adjust its border and outer shadow.", "Wähle die Kartenform und passe dann Rahmen und äußeren Schatten an.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Wähle die Schlachtzugsschwierigkeitsgrade, in denen MSUF das Kampflog startet.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Wähle die gemeinsamen Buttonfarben und den Rahmen. Layout, Tastenbelegungen und Sichtbarkeit bleiben wie eingestellt. Änderst du eine einzelne Farbe, wechselt die Bezeichnung auf „Benutzerdefiniert“.")
T("Choose the values shown on each bar.", "Wähle die Werte, die auf jeder Leiste erscheinen.")
T("Choose what the Suite tracker lists and when it steps aside.", "Wähle, was der Suite-Tracker auflistet und wann er Platz macht.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Wähle, wo die letzten Aktionen erscheinen. Tiefen haben einen eigenen Schalter; Schlachtfelder und Arenen teilen sich einen, und andere Szenarien folgen „Außerhalb von Instanzen“. Wo die Anzeige abgeschaltet ist, hört sie nicht auf deine Zauber.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Wähle, welche Blizzard-Fenster den Skin erhalten. Blizzard behält ihre Interaktionen.")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Die Wahl eines Looks aktualisiert das Skinning und jedes aktivierte Suite-Modul. Später aktivierte Module übernehmen ihn. Neue Skin-Profile beginnen mit %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "Die Bestätigung lässt sich nach deiner Entscheidung zum Überspringen auslassen. Automatisches Überspringen ist eine separate Option und überspringt auch Filme. Beide bleiben im Kampf inaktiv, und eine Fahrzeugsequenz behält immer ihre Bestätigung zum Verlassen. Dieser Helfer kann Tutorials ausblenden, das Löschwort vorausfüllen, die endgültige Bestätigung aber dir überlassen, nur die Erfolgsmeldung für Screenshots ausblenden oder beim Händler dein Charakterfenster auf dem zuletzt genutzten Reiter öffnen. Im Auktionshaus wird Blizzards Filterknopf markiert, solange „Nur aktuelle Erweiterung“ aus ist; setze den Haken dort einmal, und Blizzard behält ihn für diesen Charakter.")
T("Cinematic zone and event announcements in the Suite look.", "Filmreife Gebiets- und Ereignisankündigungen im Suite-Look.")
