T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "Clean Modern ist der Retail-Standard; MSUF Forever ist der Forever-Standard. Midnight Blue behält das ursprüngliche blaue Glas. Ändere die Farben über das Dreipunktmenü eines Abschnitts oder die gesamte Palette unter MSUF-Farben. Eigene Farbänderungen werden zu Benutzerdefiniert.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "Clean Modern nutzt matte Flächen mit weißen Akzenten. Midnight Blue behält die ursprüngliche blaue Palette, Midnight Dark neutrales anthrazitfarbenes Glas und MSUF Forever sein gedämpftes Gold. Farbänderungen werden zu Benutzerdefiniert.")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "Clean Modern, Midnight Blue, Midnight Dark und MSUF Forever sind vollständige Looks unter Stil. Farbpaletten ändern hier nur Farben; im Expertenmodus lässt sich jeder UI-Zustand einstellen.")
