T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Doppelklicke auf ein Suchergebnis, um Blizzards Bewerbungsfenster zu öffnen. Mit „Beim Doppelklick absenden“ bewirbt dich der zweite Klick zusätzlich mit den dort bereits gewählten Rollen; halte Umschalt gedrückt, um das Fenster stattdessen zu prüfen. Eine gespeicherte Notiz kann neben dem Fenster zum Kopieren erscheinen; sie wird gespeichert, wenn du die Bearbeitung beendest.")
T("Double-click a search result to open Blizzard's normal application dialog.", "Doppelklicke auf ein Suchergebnis, um Blizzards gewöhnlichen Bewerbungsdialog zu öffnen.")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Ziehe ein Fenster an seiner Oberkante; ziehe die untere rechte Ecke, um es zu skalieren. Der Minus-Button oben rechts klappt kompatible Fenster zu einem Tab zum Wiederherstellen ein. Taschen und geschützte Fenster behalten ihr ursprüngliches Verhalten.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Ziehe Ankündigungen im MSUF-Bearbeitungsmodus oder lege hier Timing, Skalierung und genaue Position fest.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "Ziehen oder Pfeiltasten zum Verschieben; Umschalt: 5, Strg: 10.")
T("Drag or use arrows to move; click for settings.", "Ziehen oder Pfeiltasten zum Verschieben; Klick für Einstellungen.")
T("Drag the bag title to move it; click for options.", "Ziehe den Taschentitel zum Verschieben; klicke für Optionen.")
T("Drag the bar's edge to move it on screen.", "Ziehe den Rand der Leiste, um sie auf dem Bildschirm zu verschieben.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Ziehe den Titel der Reagenzientasche, während sie offen ist, um sie unabhängig zu verschieben. Klicke auf den Titel für Taschenoptionen. Setze ihre Position im MSUF-Bearbeitungsmodus zurück, damit sie wieder Blizzards normalem Taschenlayout folgt.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Ziehe die Ergebniskarte im MSUF-Bearbeitungsmodus oder lege Bildschirmanker, Breite, Skalierung und Position hier fest.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Ziehe den Titel einer offenen Tasche, um sie zu verschieben. Klicke auf den Titel für Taschenoptionen. Jede Tasche behält ihre eigene Position. Blizzard zeigt rechts dein aktuelles Gold; der optionale Sitzungswert links zeigt die Änderung seit dem Login und übersteht /reload. Passe die Größe der kombinierten Tasche hier oder in ihrem Popup im MSUF-Bearbeitungsmodus an. „Position zurücksetzen“ im Bearbeitungsmodus bringt das Fenster zurück an Blizzards normalen Anker.")
T("Drag to move", "Ziehen zum Verschieben")
