T("Enchant: check = present, ! = missing or low quality, - = not needed, ? = unverified. Upgrade: + = levels remain, check / MAX = track complete. The bar shows the current track level, not upgrades previously purchased.", "Verzauberung: Haken = vorhanden, ! = fehlt oder niedrige Qualität, - = nicht nötig, ? = ungeprüft. Aufwertung: + = Stufen offen, Haken / MAX = Pfad vollständig. Der Balken zeigt die aktuelle Pfadstufe, nicht zuvor gekaufte Aufwertungen.")
