T("Enter a spell name or ID on MSUF action bars. Its buttons glow from this buff on you. A page change in combat pauses the glow until combat ends.", "Gib den Namen oder die ID eines Zaubers auf MSUF-Aktionsleisten ein. Seine Tasten leuchten durch diesen Stärkungszauber auf dir. Ein Seitenwechsel im Kampf pausiert das Leuchten bis zum Kampfende.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Gib einen Talent- oder Zaubernamen oder eine ID ein und drücke Enter. Jeder erforderliche Zauber muss erlernt sein. Ein leeres Feld entfernt diese Bedingung.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Gib einen Talent- oder Zaubernamen oder eine ID ein und drücke Enter. Der Eintrag wird ausgeblendet, sobald einer der ausgeschlossenen Zauber erlernt ist. Bedingungen werden außerhalb des Kampfes aktualisiert.")
T("Enter a texture file ID.", "Gib eine Texturdatei-ID ein.")
T("Enter a valid numeric aura ID", "Gültige numerische Aura-ID eingeben")
T("Enter a valid spell name or ID", "Gib einen gültigen Zaubernamen oder eine gültige ID ein")
T("Enter a valid talent or spell name or ID.", "Gib einen gültigen Talent- oder Zaubernamen oder eine ID ein.")
T("Enter the cast spell's name or ID. Leave empty for automatic spell matching. Timers start only from readable player cast events.", "Gib den Namen oder die ID des gewirkten Zaubers ein. Leer lassen für automatische Zauberzuordnung. Timer starten nur bei lesbaren Zauberereignissen des Spielers.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Gib bis zu 200 Gegenstands-IDs ein. Ein Knopf erscheint nur bei einem Händler und zeigt verkäufliche Stapel als Vorschau an; ein Klick öffnet die Bestätigung. Vor dem Verkauf prüft der Helfer Gegenstand, Qualität, Wert, Queststatus und Taschenplatz erneut. Anlegbare Gegenstände benötigen eine separate Freigabe.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Gib bis zu acht Zauber-IDs für Bewegungsfähigkeiten ein. Wenn du dich in Bewegung setzt, wird der erste bekannte, bereite und nutzbare Zauber kurz angezeigt. Eine gemeinsame Abklingzeit von 20 Sekunden begrenzt die Hinweise. Ohne IDs passiert nichts. Verschiebe den Hinweis im MSUF-Bearbeitungsmodus.")
T("Equal", "Gleich")
T("Equipment", "Ausrüstung")
T("Equipment category", "Kategorie Ausrüstung")
T("Equipment choices", "Ausrüstungsauswahl")
T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "Die Ausrüstungsauswahl (die Liste, die sich an einem Ausrüstungsplatz öffnet) zeigt die Gegenstandsstufe jedes Gegenstands, damit du ohne Überfahren vergleichen kannst. Die Pfeile neben den Ausrüstungsplätzen lassen sich ausblenden; halte Alt über einem Platz, um seine Auswahl zu öffnen.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "Gegenstandsstufen der Ausrüstung erscheinen oben rechts in jedem Platz. Wähle Schriftart, Kontur, Schatten und die Darstellung Weich, Scharf oder Slug. Slug hat keinen Schatten. Fehlende Gegenstandsdaten erscheinen, sobald der Client sie liefert.")
T("Equipment list only", "Nur Ausrüstungsliste")
T("Equipment set name text size", "Schriftgröße des Ausrüstungssetnamens")
T("Equipment slot %d", "Ausrüstungsplatz %d")
T("Equipment window at upgrades", "Ausrüstungsfenster bei Gegenstandsaufwertungen")
T("Equipment window at upgrades (Retail)", "Ausrüstungsfenster bei Gegenstandsaufwertungen (Retail)")
T("Erase this character's Mythic+ history? The removed runs cannot be restored.", "Mythisch+-Verlauf dieses Charakters löschen? Die entfernten Runs lassen sich nicht wiederherstellen.")
