T("Errors and destructive actions", "Fehler und destruktive Aktionen")
T("Essential bar x/y are an offset from Blizzard's bar", "X/Y von „Wichtige Abklingzeiten“ als Versatz zu Blizzards Leiste")
T("Essential cooldowns", "Wichtige Abklingzeiten")
T("Estimated time", "Geschätzte Zeit")
T("Event headline colors", "Farben der Ereignisüberschrift")
T("Every color has a purpose", "Jede Farbe hat eine Aufgabe")
T("Every color, look, geometry, font, icon, Micro Bar, Blizzard skin and HUD setting travels with the profile.", "Jede Farbe, jeder Look und jede Geometrie-, Schrift-, Symbol-, Microleisten-, Blizzard-Skin- und HUD-Einstellung wandert mit dem Profil.")
T("Every specialization already has it.", "Jede Spezialisierung hat es bereits.")
T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "Jeder Zauber dieser Leiste, auch nicht erlernte. Auf einer Buff-Leiste bietet „Zauber hinzufügen“ erhaltene Buffs wie Seele der Macht und Anregen an; „Buff auf mir“ akzeptiert auch eine Buff-Aura-ID oder einen auflösbaren Namen und verfolgt diese ID von jedem Zauberwirker. Ist „Fehlende Buffs abgedunkelt anzeigen“ aus, erscheinen nur aktive Buffs. Die Vorschau bearbeitet Einträge ebenfalls: Klick für Optionen, ziehen zum Neuordnen oder auf eine Leiste darüber, Mittelklick zum Entfernen (mit Rückgängig). Entfernte Zauber bleiben unter „Zauber hinzufügen“. Listen werden pro Spezialisierung gespeichert.")
