T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "„Anzeige freundlicher Spieler“ wählt Blizzards Einstellung, Namen für alle freundlichen Spieler, Namen nur für Gruppe / Schlachtzug oder Lebensleisten. „Nur Namen“ blendet für freundliche Spieler Blizzards Leisten, Zauber und Auren aus; NPC- und Feindplaketten ändert es nicht. „Gruppe / Außenstehend“ in der Vorschau ändert nur das Beispiel. Blizzard kann Änderungen an freundlichen Plaketten in Instanzen verbieten; diese Frames bleiben unter Blizzards Kontrolle.")
