T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "Blende Blizzards Haupttooltip im Kampf, in Instanzen oder für ausgewählte Gegenstands-, Zauber- und Einheitentooltips aus. Tooltips an MSUF-Einheiten- und Gruppenfenstern behalten ihre eigenen Sichtbarkeitseinstellungen; Aura-Tooltips behalten ihre Schalter „Tooltip anzeigen“. Jede Option funktioniert unabhängig. Ein ausgeblendeter Tooltip wird vollständig durchsichtig, damit Blizzard ihn wie gewohnt weiter verwaltet.")
