T("Hide only the selected error types. Blizzard keeps handling all other messages and their sounds. Each choice remembers and restores its previous display state when you turn it off.", "Blende nur die gewählten Fehlerarten aus. Blizzard verarbeitet alle anderen Meldungen und ihre Töne weiter. Jede Option merkt sich ihren vorherigen Anzeigestatus und stellt ihn beim Ausschalten wieder her.")
