T("Hide screenshot success notice", "Erfolgsmeldung für Screenshots ausblenden")
T("Hide spell out of range", "„Zauber außer Reichweite“ ausblenden")
T("Hide spell tooltips", "Zaubertooltips ausblenden")
T("Hide target arrows on friendly plates", "Zielpfeile auf freundlichen Plaketten ausblenden")
T("Hide the Suite Micro Bar when any selected condition is true. The health condition uses your character's health; at full health the transparent bar can still receive clicks. MSUF Edit Mode shows the bar for placement. Blizzard layout keeps Blizzard's visibility.", "Blendet das Suite-Mikromenü aus, wenn eine gewählte Bedingung zutrifft. Die Gesundheitsbedingung nutzt die Gesundheit deines Charakters; bei voller Gesundheit kann die transparente Leiste weiterhin Klicks empfangen. Der MSUF-Bearbeitungsmodus zeigt die Leiste zum Platzieren. Das Blizzard-Layout behält Blizzards Sichtbarkeit.")
T("Hide the arrows beside gear slots", "Pfeile neben den Ausrüstungsplätzen ausblenden")
T("Hide the charge count at zero", "Aufladungsanzahl bei null ausblenden")
