T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Halte Alt, um die ID eines Gegenstands, Zaubers, einer Kreatur, Quest, Währung oder temporären Waffenverzauberung im Tooltip zu sehen, oder drücke Alt bei offenem Tooltip; die IDs bleiben, bis der Tooltip neu aufgebaut wird. Zaubersymbol-IDs und Blizzards Währungsdaten deiner anderen Charaktere sind optional, und diese Daten kommen in einen offenen Tooltip, sobald sie eintreffen. Keine ID oder Menge erscheint, wenn der Client sie privat hält.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "Halte Alt gedrückt, um Gegenstands-, Zauber-, Kreaturen-, Quest-, Währungs- und temporäre Waffenverzauberungs-IDs im Haupttooltip anzuzeigen.")
T("Hold Midnight Artisan payouts while Shard of Dundun is capped", "Midnight-Handwerksauszahlungen am Limit für Splitter von Dundun zurückhalten")
T("Hold Shift to pause. Quests with a money cost and quests with a reward choice always stay manual.", "Halte die Umschalttaste zum Pausieren. Quests mit Goldkosten oder Belohnungsauswahl bleiben immer manuell.")
T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "Halte die gewählte Taste gedrückt, während du auf Geist freilassen klickst. Der Freilassen-Button bleibt bis dahin ausgeblendet; Wiederbelebung und Todesrückblick bleiben verfügbar. Wähle, wo der Schutz gelten soll. Blizzards automatischer Freilassen-Timer bleibt unverändert.")
T("Hold to release", "Taste zum Freilassen")
