T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "Im Schlachtzug wird der Tracker an seiner gewohnten Stelle zur Begegnungsansicht: Bossname, Pull-Timer, die gerade aktiven Bosse mit ihrer Gesundheit, dein bester Wipe und dein schnellster Kill. Phasen kommen von DBM oder BigWigs, wenn eines installiert ist; sonst bleibt die Phase offen. Ein Wipe mit mehr besiegten Bossen schlägt einen mit weniger, bei gleicher Zahl gewinnt der mit weniger verbliebener Bossgesundheit. Jeder Charakter führt eigene Aufzeichnungen. Die Bossgesundheit erscheint nur, solange der Client sie preisgibt.")
