T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Behalte das Blizzard-Raster oder wähle ein Suite-Raster, tatsächliche Taschengruppen oder Kategorien. Über Kategorien bearbeiten im Taschenfenster kannst du Kategorien erstellen, umbenennen, sortieren oder deaktivieren; ziehe Gegenstände auf eine Seitenleistenkategorie, um sie zuzuweisen. Für größere Inventare kannst du scrollen oder Zurück und Weiter nutzen; im Kampf werden alle Plätze auf einmal angezeigt. Zusammengefasste Stapelzahlen sind rein visuell; an Bank, Gildenbank, Post, Handel, Auktionshaus und beim Händler werden immer die tatsächlichen Stapel angezeigt.")
