T("Lightweight meter windows for damage, healing, interrupts, dispels, deaths and damage taken. They read the client's own combat data; Blizzard's meter window stays hidden while this module is active.", "Schlanke Fenster für Schaden, Heilung, Unterbrechungen, Bannungen, Tode und erlittenen Schaden. Sie lesen die eigenen Kampfdaten des Clients; Blizzards Schadensanzeige bleibt ausgeblendet, solange dieses Modul aktiv ist.")
T("Lilac", "Flieder")
T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "Beschränke die ganze Hervorhebung auf den Kampf, auf Instanzen oder die offene Welt und gib dann Zeigerring, globaler Abklingzeit und Zauberfüllung je eine eigene Kampfregel. Solange sie verborgen ist, folgt nichts dem Zeiger.")
