T("List group pets", "Gruppenbegleiter auflisten")
T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "Listet mitgeführte Edelsteinarten neben Blizzards Sockelfenster auf. Prüfe jeden Edelstein über seinen normalen Taschen-Tooltip und bestätige die Eignung im nativen Sockelfenster, bevor du ihn einsetzt.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "Listet in Dungeons für fünf Spieler die Zauber angreifbarer Gegner mit Namensplakette auf, die ältesten zuerst; Leiste und Zeit jedes Zaubers führt das Spiel. Zauber, Ziel, Markierung und Unterbrechbarkeit hält das Spiel vor Addons verborgen, daher wird nie danach sortiert oder gefiltert: Abblenden oder Ausblenden nutzt die Wichtig-Markierung des Spiels (ein ausgeblendeter Zauber behält seinen Platz in der Liste), Schlachtzugsmarkierungen sitzen auf dem Zaubersymbol, und die Bereit-Markierung, ein Randstreifen oder die ganze Leiste, erscheint auf unterbrechbaren Zaubern, solange deine Unterbrechung abklingbereit ist. Das Abdunkeln prüft viermal pro Sekunde, ob deine Unterbrechung jeden gelisteten Gegner erreicht; ein Zauber, der sich nicht prüfen lässt, bleibt hell. Die Unterbrechung wird aus Talenten und Begleiter ermittelt, außer du gibst eine Zauber-ID ein. Der MSUF-Bearbeitungsmodus zeigt Beispielzauber zum Platzieren der Liste.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "Listet in Dungeons für fünf Spieler die Zauber gegnerischer Namensplaketten auf, die ältesten zuerst, mit Zeiten, die das Spiel führt.")
