T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline deckt Schurkengifte, die Fläschchen, Verstärkungsrunen und Waffenöle dieser Saison sowie den Essens-Buff Satt ab. Jede Kategorie verwendet beim Klick den ersten passenden Gegenstand in deinen Taschen; ein dafür eingetragener Gegenstand wird zuerst versucht. Essen wird über die Ess-Zauber des Spiels in deinen Taschen gefunden: das eingetragene Essen zuerst, dann das neueste. Mit der grauen Erinnerung bleibt eine leere Kategorie ohne Klickaktion sichtbar. Meucheln bevorzugt Tödliches Gift, Gesetzlosigkeit und Täuschung bevorzugen Sofort wirkendes Gift. Drachengehärtete Klingen erlaubt zwei Gifte pro Kategorie. Öle zielen auf angelegte Waffen; bekannte Schamanen- oder Paladinverzauberungen unterdrücken automatische Öle.")
