T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko verwendet moderne Namensplaketten, mittlere Größe und dieselben Balkenmaße auf Retail und Forever. Gildennamen und Titel beeinflussen auch Namen in der Spielwelt. Belege Freundliche NSC-Namensplaketten umschalten unter MSUF Suite in Blizzards Tastenbelegung. Der Importschutz bewahrt deine aktuellen Namensplaketten beim Import eines vollständigen Suite-Profils; gezielte Namensplakettenimporte ersetzen sie weiterhin.")
