T("Open Blizzard's raid tools, start a pull countdown, or mark one party tank or healer by command or opt-in automation.", "Öffne Blizzards Schlachtzugswerkzeuge, starte einen Pull-Countdown oder markiere genau einen Tank oder Heiler der Gruppe per Befehl oder optional automatisch.")
