T("Open new containers", "Neue Behälter öffnen")
T("Open new containers (Retail)", "Neue Behälter öffnen (Retail)")
T("Open newly acquired loot containers one at a time outside combat. Hold Shift to leave them manual.", "Öffne neu erhaltene Beutebehälter außerhalb des Kampfes einzeln. Halte Umschalt gedrückt, um sie selbst zu öffnen.")
T("Open or show the module before moving it.", "Das Modul vor dem Verschieben einblenden.")
T("Open run history", "Laufverlauf öffnen")
T("Open the MSUF menu to find the Suite pages. MSUF must be installed and enabled.", "Öffne das MSUF-Menü, um die Suite-Seiten zu finden. MSUF muss installiert und aktiviert sein.")
T("Open the map after setting a waypoint", "Karte nach dem Setzen eines Wegpunkts öffnen")
T("Open this page out of combat to load the cooldown manager.", "Öffne diese Seite außerhalb des Kampfes, um den Cooldown-Manager zu laden.")
T("Open world", "Offene Welt")
T("Open your equipment window beside an item upgrade merchant and close only the window MSUF opened.", "Öffne dein Ausrüstungsfenster neben einem Händler für Gegenstandsaufwertungen. Geschlossen wird nur das Fenster, das MSUF selbst geöffnet hat.")
T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "Öffnet dein Charakterfenster auf dem zuletzt genutzten Reiter, wenn du einen Händler für Gegenstandsaufwertungen ansprichst. Schließt nur ein Fenster, das dieser Helfer geöffnet hat, und wartet zum Öffnen oder Schließen das Kampfende ab.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Optionale Blizzard-Einstellungen für Chat, Karte, Ton und das Bildschirmblinken bei wenig Gesundheit oder alternative Blendeffekte. MSUF stellt den vorherigen Wert wieder her, wenn du eine Option oder diesen Helfer ausschaltest. Eigene Änderungen in den Blizzard-Einstellungen bleiben erhalten.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "Optionale Grafik- und Abstandseinstellungen. Nutze den MSUF-Bearbeitungsmodus für Position, Feinverschiebung, Zurücksetzen, Rückgängig und Wiederholen.")
T("Optional shortcuts for tutorials, item deletion and screenshot notices.", "Optionale Erleichterungen für Tutorials, Gegenstandslöschung und Screenshotmeldungen.")
T("Optionally hide the main tooltip in combat, instances or for selected content types.", "Blende den Haupttooltip optional im Kampf, in Instanzen oder für ausgewählte Inhaltsarten aus.")
