T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "Priorität: Fokus, sichere Tank-Aggro, Bedrohung, fremd getaggt, Quest, neutral, dann NPC-Typ. Schaltest du den Fokus aus, greift die nächste Regel. Deaktivierte Bedrohungsüberschreibungen behalten Blizzards aktive Bedrohungsfarbe. Der Tankmodus nutzt deine tatsächliche Rolle; Warnungen funktionieren auch für Schaden/Heiler. Geheime Werte bleiben bei Blizzard.")
