T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "Repariert die Ausrüstung und verkauft graue Gegenstände, sobald ein Händler geöffnet wird. Halte die Umschalttaste, um den Verkauf zu überspringen.")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "Repariert nur, wenn die Kosten innerhalb deines Limits liegen. Gildengold wird zuerst genutzt, wenn erlaubt.")
T("Replace Blizzard event banners", "Blizzards Ereignisbanner ersetzen")
T("Replace objectives with the Mythic+ timer during a key", "Ziele während eines Schlüssels durch den Mythisch+-Timer ersetzen")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "Ersetzt die Seiten des Händlers durch eine Liste; scrolle mit dem Mausrad oder der Leiste. Rechtsklick kauft, Linksklick nimmt einen Gegenstand auf und Umschalt-Klick fragt nach einer Menge; Verlinken und Vorschau funktionieren wie gewohnt. Käufe mit Währungen oder Gegenständen oder ab 150 Gold fragen zuerst nach einer Bestätigung. Der Rückkauf-Reiter behält Blizzards Darstellung. Lege einen Gegenstand aus deinen Taschen auf die Liste oder klicke damit darauf, um ihn zu verkaufen; einen noch erstattbaren fragt sie, ob er erstattet werden soll.")
T("Report junk sale requests in chat", "Plunderverkauf im Chat melden")
T("Reports group member deaths in chat during combat.", "Meldet Todesfälle von Gruppenmitgliedern im Kampf im Chat.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "Meldet den ersten beobachteten Tod jedes Gruppenmitglieds im Kampf. Lokaler Chat, Bildschirmmeldung und Sound sind getrennt wählbar. Gleichzeitige Tode teilen sich einen Sound. Optional wird dein eigener Tod einbezogen. Die Erfassung läuft nur, solange du in einer Gruppe und im Kampf bist.")
T("Reputation", "Ruf")
