T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "Stellt die Standardzauber und -buffs dieser Leiste für deine Spezialisierung wieder her. Andere Leisten und Spezialisierungen bleiben unverändert. Du kannst das rückgängig machen.")
T("Results and details", "Ergebnisse und Details")
T("Resurrection offers", "Wiederbelebungsangebote")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "Nur für Retail-Druiden. Jedes eingehende Flüstern im Kampf ist ein möglicher Anregen-Hinweis; der Nachrichtentext lässt sich während der Chatsperre nicht zuverlässig prüfen. Die Warnung wartet auf eine öffentlich bekannte Abklingzeit von Anregen oder zeigt einen allgemeinen Hinweis, wenn die Bereitschaft nicht verfügbar ist. Ein bevorzugtes Ziel kann auf einem MSUF-Gruppenframe umrandet werden, der außerhalb des Kampfes ermittelt wird. Der MSUF-Bearbeitungsmodus zeigt eine Vorschau der Warnung und bearbeitet ihre Position und Größe.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Nur Retail. Wird angezeigt, solange Skyriding verfügbar ist, oder optional nur im Flug. Wähle Balken oder Blizzard-Vigor-Edelsteine; Skalierung und Wiederaufladesound sind optional. Separate Balkenhöhen, Surge-Icongröße und Geschwindigkeitswertabstände stehen unter Text und Balken. MSUF-Bearbeitungsmodus zeigt eine HUD-Vorschau. Unbekannte Ladungen erscheinen als Striche.")
T("Return to the current fight when combat starts", "Bei Kampfbeginn zum aktuellen Kampf wechseln")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "Setzt diese Spezialisierung auf ihre kurze Liste wichtiger Schlachtzugszauber zurück. Deine anderen Leisten und Spezialisierungen bleiben unverändert. Du kannst das rückgängig machen.")
