T("Selected currencies appear above the bag footer. Click Gold history for recorded character balances and 30 days of this character's income and spending, by local date. Other characters show their last recorded balance. The history starts when enabled and does not reconstruct earlier transactions; Clear saved character gold removes the history and the balances.", "Ausgewählte Währungen erscheinen über der Fußzeile des Taschenfensters. Klicke auf Goldverlauf für erfasste Charakterstände und die Einnahmen und Ausgaben dieses Charakters der letzten 30 Tage, nach lokalem Datum. Andere Charaktere zeigen den zuletzt erfassten Goldstand. Die Aufzeichnung beginnt mit der Aktivierung und rekonstruiert keine früheren Transaktionen; Gespeicherte Goldstände löschen entfernt den Verlauf und die Stände.")
T("Selected data", "Ausgewählter Datentext")
T("Selected pages and list entries", "Ausgewählte Seiten und Listeneinträge")
T("Selected profession outfits and cosmetic auras are removed outside combat. Fishing is excluded. Noggenfogger skeleton removal also removes its underwater-breathing effect. Client refusal stops this helper until settings change.", "Ausgewählte Berufskleidung und kosmetische Auren werden außerhalb des Kampfes entfernt. Angeln ist ausgenommen. Beim Entfernen des Noggenfogger-Skeletts entfällt auch dessen Unterwasseratmung. Verweigert der Client das Entfernen, stoppt die Hilfe bis zur nächsten Einstellungsänderung.")
