T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "Zeige das Wetter als Text, Symbol oder beides. Wähle Blizzard-Symbole oder eigene Motive im Forever-Design. Bei reiner Symbolanzeige steht der Wettername weiterhin im Tooltip.")
T("Show weekly reward item levels", "Stufen der Wochenbelohnungen anzeigen")
