T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Wechsle mit der Schaltfläche unter dem Bankfenster zwischen nativen Fächern, zusammengefasster Bank, zusammengefasster Kriegsmeutenbank und gemeinsamen Kategorien. Gemeinsame Kategorien enthalten zugängliche Charakter- und Kriegsmeutenbankfächer. Bankfächer verwalten öffnet Blizzards Kauf-, Einzahlungs- und Facheinstellungen. Jeder Platz behält seine eigene Gegenstandsaktion und Bankstapel werden nie zusammengefasst; ein Klick auf einen Gegenstand der Kriegsmeutenbank wählt zuerst Blizzards Kriegsmeutenbank-Reiter, und ein erstattbarer Gegenstand fragt nach, bevor er in die Kriegsmeutenbank wandert.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "Schalte hier einzelne Leisten ein oder aus. Beim Einschalten wird ihre vorherige Sichtbarkeitsregel wiederhergestellt. Unter Layout kannst du die oben ausgewählte Leiste anpassen.")
