T("The Glass material with MSUF Forever graphite, ivory and muted-gold colors.", "Das Glas-Material mit den MSUF-Forever-Farben Graphit, Elfenbein und gedämpftes Gold.")
T("The Great Vault is available only in Retail", "Die Große Schatzkammer gibt es nur in Retail")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "Der Mapko-Skin für Blizzard-Namensplaketten. Blizzard steuert weiterhin Leben, Bedrohung, Zauber, Auren, Auswahl und Klicks.")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "Die Suite-Seite für den Cooldown-Manager (CDM) zeigt von Blizzard erfasste Abklingzeiten und Stärkungszauber als Leisten, die du frei anordnen und gestalten kannst.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "Auf der Suite-Seite „Minikarte“ gestaltest du die Minikarte selbst: Größe, Form, Rahmen, Zoom, Knöpfe und Infotexte. Das MSUF-eigene Minikartensymbol findest du unter „Sonstiges“.")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "Auf der Suite-Seite „Namensplaketten“ gestaltest du Blizzards feindliche und freundliche Namensplaketten. Die MSUF-Aurenfilter bestimmen nur, ob reine Namensplaketten-Auren auf MSUF-Fenstern angezeigt werden.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, and tracked achievements. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "Die Suite zeichnet ihren eigenen Tracker und verbirgt den von Blizzard, solange sie läuft. Einträge werden in Gruppen sortiert: die fokussierte Quest, Kampagnen- und wichtige Quests, abgabebereite Quests, normale Quests, Weltquests, nahe Bonusziele, Szenario- und Tiefenschritte sowie verfolgte Erfolge. Im Schlachtzug kann er ganz verschwinden, nur während eines Bosskampfs verschwinden oder bei jedem Raidkampf die normale Liste pausieren; die Begegnungsansicht läuft dann weiter. Questsymbole gibt es als Suite-Buchstaben oder als Blizzard-Symbole, und die Überschriftszeile lässt sich ausschalten. Die Tastenbelegung „Verfolgtes Questitem benutzen“ verwendet das Item der fokussierten Quest, sonst das erste nutzbare, und wählt ein neues Item nur außerhalb des Kampfes. Linksklick auf einen Gruppennamen klappt ihn ein, auf eine Quest öffnet ihren Logeintrag; Rechtsklick zeigt weitere Aktionen.")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "Die Suite rahmt Blizzards originale Microbuttons ein. Grafik, Klicks, Tooltips, Aktivierungszustände und Benachrichtigungen bleiben original. Warteschlangen- und FPS-Anzeige bleiben an ihrer Position aus Blizzards Bearbeitungsmodus. Es läuft kein wiederkehrendes MSKIN-Update.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "Die Suite-Optik gibt Blizzards Dialogen ein dunkles Feld, die Suite-Schrift setzt Schrift und Größe ihres Texts; beides geht einzeln, und ohne sie behalten Dialoge Blizzards Optik und Schriften. Eine Mindesthöhe macht kurze Dialoge höher, nachdem Blizzard sie bemessen hat; 0 behält Blizzards Höhe. Eine eigene Position verschiebt den ersten Dialog und die, die Blizzard darunter stapelt; platziere ihn und setze die Höhe im MSUF-Bearbeitungsmodus.")
T("The Suite skin engine is unavailable.", "Die Suite-Skin-Engine ist nicht verfügbar.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "Das gewählte Profil liefert alle Einstellungen. Lege fest, welche Suite-Module darin aktiviert sind.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "Der Klassenbuff wird nur einbezogen, wenn dein Charakter ihn kennt. Gib Selbstbuff-Zauber-IDs getrennt durch Leerzeichen oder Kommas ein. Für ein Verbrauchsgut gib Gegenstands-ID:Aura-ID ein; trenne Paare mit Kommas. Es werden insgesamt bis zu 12 Erinnerungen angezeigt. Waffenverzauberungsgegenstände nutzen den Verzauberungsstatus der Waffen- oder Schildhand.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "Die kombinierte Tasche und die Reagenzientasche nutzen ein Suite-Panel mit eigener Kopfzeile, Rahmen und Akzentlinie. Setze die Hintergrunddeckkraft auf 0 für ein transparentes Fenster; Gegenstandsplätze bleiben sichtbar.")
T("The combined bag setting is protected on this client", "Die Einstellung für kombinierte Taschen ist auf diesem Client geschützt")
T("The configuration cannot be opened during combat.", "Die Konfiguration kann im Kampf nicht geöffnet werden.")
T("The cooldown manager is not loaded.", "Der Cooldown-Manager ist nicht geladen.")
T("The cooldown manager needs an update. Reload the interface.", "Der Cooldown-Manager braucht ein Update. Lade die Oberfläche neu.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "Der Cooldown-Manager wurde zurückgesetzt: Einstellungen, Zauberlisten und Zauberoptionen.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "Der Countdown wechselt unter dieser Sekundenzahl in die Warnfarbe. Alle Leisten: die Einstellung des Textabschnitts.")
T("The dark sweep over the icon while it counts down.", "Der dunkle Wischeffekt über dem Symbol, während es herunterzählt.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "Die Standardschriftart folgt den MSUF-Schriftarten, die Standardgröße folgt Blizzards Chatgröße. Wähle „Blizzard-Chatschrift“, um deren eigene Schrift zu behalten. Slug hat keinen Schatten.")
T("The dungeon's timer", "Den Timer des Dungeons")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "Die Engine ruht, bis ein Lebenszyklus-Ereignis oder eine ausdrückliche Aktion Arbeit erfordert.")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "Die globale Abklingzeit kann den Ring verlassen und in einem festen Kreis mit eigener Größe und Deckkraft erscheinen, auch neben Zaubern. Platziere ihn im MSUF-Bearbeitungsmodus; seine Schaltfläche dort funktioniert, solange diese Option an ist.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "Die Kopfzeile zeigt Anzeige und Kampf. Ihre Buttons wechseln Anzeige und Kampf direkt im Fenster.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "Der Schlüsselsteinhinweis bleibt lokal. Die optionale Gruppenankündigung leitet nur Blizzards bestätigte Resetmeldung unmittelbar nach deiner eigenen Resetanfrage weiter, solange du Gruppenleiter bist. Fehlversuche und Resets anderer Spieler werden nicht angekündigt.")
T("The macro builder is available only in Retail", "Der Makro-Generator ist nur in Retail verfügbar")
T("The macro exceeds the 255-character limit", "Das Makro überschreitet die Grenze von 255 Zeichen")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "Die Karte wächst oder schrumpft auf die gewählte Breite und Höhe, solange der Mauszeiger darüber ist, und kehrt dann zu ihrer normalen Größe zurück. Eine runde Karte hält ihre Höhe gleich ihrer Breite.")
T("The merchant's offers changed; nothing was bought.", "Das Angebot des Händlers hat sich geändert; es wurde nichts gekauft.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "Das gesamte Angebot des Händlers in einer scrollbaren Liste mit Preisen, Qualitätsfarben und Gegenstandsstufen.")
T("The minutes below", "Die Minuten unten")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "Das Mausrad zoomt die Karte. Der Mittelklick führt die gewählte Aktion aus; Links- und Rechtsklick funktionieren wie gewohnt.")
T("The native input box keeps autocomplete, links and chat commands.", "Das originale Eingabefeld behält Autovervollständigung, Links und Chatbefehle.")
T("The normal warning time", "Die normale Warnzeit")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "Die optionale Glyphenebene ändert das Aussehen, während Blizzard Klicks, Tooltips, Aktivierungszustände und Benachrichtigungen behält. Warteschlangen- und FPS-Anzeige bleiben an ihrer Position aus Blizzards Bearbeitungsmodus. Es läuft kein wiederkehrendes MSKIN-Update.")
T("The options module could not be loaded: %s", "Das Optionsmodul konnte nicht geladen werden: %s")
T("The options module did not finish initializing.", "Das Optionsmodul wurde nicht vollständig initialisiert.")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "Die Gruppentabelle wächst in Stufen: Charaktere mit Ausrichtung und Wertung, dann die Kampfwerte aus Blizzards Schadensmesser, dann die im Chat gesehene Beute. Jeder Charakter behält seine letzten Runs; öffne den neuesten hier oder mit /msufruns und blättere zu älteren. Das Löschen eines Runs verlangt einen zweiten Klick. Die Karte kann warten, bis du das Beutefenster der Truhe schließt.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "Die Vorschau und alle Abschnitte darunter bearbeiten diese Leiste. Gemeinsame eigene Gruppen beginnen mit einer separaten Liste ausdrücklich gewählter Zauber-, Aura- und Gegenstands-IDs; das Deaktivieren der Freigabe stellt die vorhandene Spezialisierungsliste wieder her.")
T("The preview needs the cooldown manager.", "Die Vorschau braucht den Cooldown-Manager.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "Der Schnellschalter oben merkt sich diesen Modus, wenn du die Leiste ausschaltest. Wähle „Nie“, um sie ausgeblendet zu lassen.")
T("The settings you change most. Attach the bar to another bar or to your player frame to keep them together; the gap is the space between them. Center keeps the first cooldown icon in the middle and adds the next icons right, left, right, left. Visible buffs stay compact; on a horizontal mixed bar, player and target buffs grow outward from the center on one row.", "Die Einstellungen, die du am häufigsten änderst. Hefte die Leiste an eine andere Leiste oder an deinen Spielerframe, um beide zusammenzuhalten; der Abstand ist der Raum dazwischen. „Mitte“ hält das erste Abklingzeitsymbol in der Mitte und fügt die nächsten Symbole rechts, links, rechts, links hinzu. Sichtbare Buffs bleiben kompakt; auf einer horizontalen gemischten Leiste wachsen Spieler- und Zielbuffs in einer Reihe von der Mitte nach außen.")
T("The socket window is available only in Retail", "Das Sockelfenster ist nur in Retail verfügbar")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "Die Stapelbedingung verwendet Leuchten ab Stapeln und Stapelvergleich. Das Fehlen eines Stärkungszaubers kann über die native Aura-Slot-API kein Leuchten im Kampf steuern.")
T("Theme", "Thema")
T("Theme-colored icon outline", "Symbolumriss in Themenfarbe")
T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Diese Einstellungen gelten für alle Leisten. Das eigenständige Unterstützungssymbol folgt Blizzards Hervorhebung der Kampfunterstützung; aktiviere sie in den Kampfoptionen des Spiels. Die Position lässt sich im MSUF-Bearbeitungsmodus ändern. Tastendrücke auf Aktionsleisten werden nur mit den MSUF-Suite-Aktionsleisten auf Abklingzeitsymbolen angezeigt.")
T("These apply to every bar:", "Diese gelten für jede Leiste:")
T("These choices apply to this spell on every bar and specialization.", "Diese Einstellungen gelten für diesen Zauber auf jeder Leiste und in jeder Spezialisierung.")
T("These settings apply to all bars until a bar uses its own style.", "Diese Einstellungen gelten für alle Leisten, bis eine Leiste ihren eigenen Stil nutzt.")
T("Thick outline", "Dicke Kontur")
T("Thick outline + SLUG", "Dicke Kontur + SLUG")
T("Thick outline + shadow", "Dicke Kontur + Schatten")
