T("This bar sits on Blizzard's Essential bar, which your MSUF frames follow. Move it in Blizzard's Edit Mode.", "Diese Leiste liegt auf Blizzards Leiste „Wichtige Abklingzeiten“, der deine MSUF-Frames folgen. Verschiebe sie im Blizzard-Bearbeitungsmodus.")
T("This bar takes the place of %s, which is off. Move that bar, or attach this one elsewhere.", "Diese Leiste nimmt den Platz von %s ein (ausgeschaltet). Verschiebe jene Leiste oder hefte diese woanders an.")
T("This bar's own options are not used by the %s type; the settings below apply to every bar.", "Die eigenen Optionen dieser Leiste werden vom Typ %s nicht genutzt; die Einstellungen unten gelten für jede Leiste.")
