T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "Hake jeden Dämon an, den du draußen haben willst; auch Dämonen, die dein Charakter noch nicht gelernt hat, lassen sich anhaken. Ein beschworener Dämon ohne Haken bekommt einen Hinweis, solange einer deiner angehakten Dämonen beschworen werden kann. Ein anderes Aussehen eines Dämons zählt als dieser Dämon, sobald du ihn einmal in diesem Aussehen beschworen hast.")
