T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "Zeitstempel nutzen Blizzards Chateinstellung in allen Chatfenstern. Kopieren ist standardmäßig aus; wenn aktiviert, verschiebe seinen Button mit X/Y, wähle eine Nachricht und drücke dann Strg+C. Der angezeigte Zeitstempel wird mitkopiert, wenn Zeitstempel an sind. Die Nachrichtenwerkzeuge lassen das Kampflog unberührt (seine eigenen Einstellungen können jeder Zeile einen Zeitstempel geben); seine Zeilen wecken das Ausblenden bei Inaktivität trotzdem. Der gespeicherte Verlauf gehört zu diesem Charakter.")
