T("Turn off Show combat time to hide both the duration in every meter header and the separate floating timer. The two switches below let you show either one independently.", "Schalte „Kampfzeit anzeigen“ aus, um sowohl die Dauer in jeder Anzeigekopfzeile als auch den separaten schwebenden Timer auszublenden. Mit den beiden Schaltern unten zeigst du jedes davon unabhängig an.")
T("Turn on \"%s\" to change this.", "Schalte „%s“ ein, um dies zu ändern.")
T("Turn on Secondary stats in the MSUF Suite options to use the FPS readout.", "Schalte „Sekundärwerte“ in den MSUF-Suite-Optionen ein, um die FPS-Anzeige zu nutzen.")
T("Turn on another bar first.", "Schalte zuerst eine andere Leiste ein.")
T("Turn speech bubbles off inside instances", "Sprechblasen in Instanzen ausschalten")
T("Turn the cooldown manager on in Basics to edit these.", "Schalte den Cooldown-Manager in den Grundlagen ein, um diese zu bearbeiten.")
T("Turn the cooldown manager on in Basics to play it.", "Schalte den Cooldown-Manager in den Grundlagen ein, um die Vorschau abzuspielen.")
T("Tutorials and help overlays", "Tutorials und Hilfe-Einblendungen")
T("Two rows", "Zwei Reihen")
T("Two-color material gradients", "Zweifarbige Materialverläufe")
T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "Gib /keys oder /msufkeys ein, um deinen aktuellen Schlüsselstein zu sehen. Ergänze party, raid oder instance, um ihn im jeweiligen Kanal zu teilen. /keys group fragt Schlüsselsteine von Gruppenmitgliedern ab, die diesen Suite-Helfer verwenden. Der kurze Befehl /keys wird nur genutzt, wenn ihn kein anderes Addon belegt. In Dungeons und Schlachtzügen sperrt Blizzard den Chat für Addons; dein Schlüssel wird dann nur dir angezeigt.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. The guild chat in the Guild & Communities window can be covered as well; other communities stay visible. Reveal the chat again with the click chosen here. Messages keep arriving underneath.", "Gib /msufguildprivacy ein oder nutze den kleinen AN/AUS-Knopf über dem Hauptchatfenster. Jedes Chatfenster mit Gilden- oder Offiziersnachrichten wird vollständig verdeckt, in gemischten Fenstern auch die anderen Kanäle. Auch der Gildenchat im Fenster Gilde & Communitys kann verdeckt werden; andere Communitys bleiben sichtbar. Mit dem hier gewählten Klick wird der Chat wieder sichtbar. Nachrichten treffen darunter weiter ein.")
T("Type /msufmacro to preview a mouseover ally, mouseover enemy or focus enemy macro. Enter a spell name or ID, then explicitly create a character macro outside combat. Drag it from /macro to your action bar.", "Gib /msufmacro ein, um eine Vorlage für ein Makro mit verbündetem Mausoverziel, feindlichem Mausoverziel oder feindlichem Fokusziel anzusehen. Gib einen Zaubernamen oder eine ID ein und erstelle das Charaktermakro außerhalb des Kampfes ausdrücklich per Klick. Ziehe es über /macro auf deine Aktionsleiste.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "Gib /msufraid ein, um Blizzards Schlachtzugsverwaltung aufzuklappen, /msufpull [1-60] für den nativen Countdown oder /msufmark tank bzw. /msufmark healer, um genau ein eindeutig bestimmbares Gruppenmitglied zu markieren. Optionale automatische Markierungen funktionieren nur für einen eindeutigen Tank oder Heiler in einer Fünfergruppe und nur als Leiter oder Assistent. Vorhandene und belegte Markierungen bleiben erhalten. Countdowns, Markierungen und Bereitschaftschecks warten, solange Blizzard sie im Kampf, in Bosskämpfen und Schlüsselsteinen sperrt; automatische Markierungen folgen danach.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "Nutze /way x y für die aktuelle Karte oder /way KartenID x y. /msufway funktioniert immer. Der kurze Befehl /way wird nur genutzt, wenn kein anderes Addon ihn belegt.")
T("Type a name or ID to filter", "Name oder ID zum Filtern eingeben")
T("Type a spell, then preview the macro", "Gib einen Zauber ein und sieh dir dann das Makro an")
T("Type a texture file ID and press Enter to show another icon. Empty follows the game.", "Gib eine Texturdatei-ID ein und drücke die Eingabetaste, um ein anderes Symbol zu zeigen. Leer folgt dem Spiel.")
T("Type an ID or a spell name.", "Gib eine ID oder einen Zaubernamen ein.")
